  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a materially higher cap, supported by the risk profile and diligence"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek lower thresholds and a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period and separate, appropriately longer periods for tax and other latent liabilities."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "The Seller’s proposal to subject capacity and title to the same cap and time limits is not acceptable"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve separate treatment for debt/price adjustments, specific indemnities, fraud, fraudulent or deliberate misrepresentation, equitable relief and any other agreed non-warranty remedies."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Do not accept blanket data-room or public-register disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject blanket knowledge and non-reliance bars."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require delivery of valid written consent and satisfaction of all associated conditions before Completion."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require Riverlark repayment and discharge at or before Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Rework the funds flow for the bonuses and on-costs."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden and secure the Ironquay IP protection."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "a specific indemnity for losses, response costs, claims and regulatory consequences arising from the incident."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "The three AUD 110,000 renewals total AUD 330,000. The disclosures do not establish whether the commitments are terminable, accrued, unavoidable or ordinary course."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject applying these limitations to all Claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "does not itself verify beneficial ownership, absence of liens or completeness of the capitalisation. Verify the register and supporting corporate records."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Renegotiate the cap, thresholds, survival periods and remedy provisions, with distinct protection for fundamental/title, tax, fraud and specific indemnities."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

